//Generated by copilot, not my code, but I verified simulation manually
//This test bench verifies a 4-bit binary decoder.
module binary_decoder_tb;
    reg en;
    reg [3:0] binary_num;
    wire [15:0] decoded_num;
    reg [15:0] expected;
    integer i;

    binary_decoder dut (
        .en(en),
        .binary_num(binary_num),
        .decoded_num(decoded_num)
    );

    initial begin
        en = 1'b1;
        for (i = 0; i < 16; i = i + 1) begin
            binary_num = i;
            expected = 16'b1 << i;
            #1;
            if (decoded_num !== expected)
                $fatal(1, "Input %0d: expected %h, got %h", i, expected, decoded_num);
        end

        en = 1'b0;
        binary_num = 4'b1010;
        #1;
        if (decoded_num !== 16'b0)
            $fatal(1, "Disabled output should be zero, got %h", decoded_num);

        $display("PASS: binary_decoder tests passed");
        $finish;
    end
endmodule
